SET @task_id=208;
SELECT 'SNAPSHOT' section,NOW(3) observed_at,e.id,e.seq,e.source_file_name,e.attempt_no,e.execution_status,e.stage,e.reason_code,e.reason_message,e.active_pull_wave_id,w.wave_no,w.next_call_seq,w.planned_call_count,SUM(m.pull_status=2) success,SUM(m.pull_status IN (0,1,4)) remaining,FROM_UNIXTIME(e.started_at/1000) started_at,FROM_UNIXTIME(e.finished_at/1000) finished_at,FROM_UNIXTIME(e.last_business_executed_at/1000) last_business_at FROM pull_task_group_execution e LEFT JOIN pull_task_pull_wave w ON w.id=e.active_pull_wave_id JOIN pull_task_material_member m ON m.group_execution_id=e.id WHERE e.task_id=@task_id GROUP BY e.id ORDER BY e.seq,e.attempt_no;
SELECT 'CURRENT_CALL' section,c.id,c.group_execution_id,c.call_status,c.command_id,c.planned_material_count,(SELECT COUNT(*) FROM pull_task_material_member m WHERE m.pull_call_id=c.id) bound_materials,(SELECT COUNT(*) FROM pull_task_pull_call_member_attempt a WHERE a.pull_call_id=c.id AND a.lifecycle_status=1) planned_attempts FROM pull_task_pull_call c WHERE c.id IN (8916,8934);
SELECT 'MEMBER_HISTORY' section,a.id,a.group_execution_id,a.pull_wave_id,a.pull_call_id,a.participant_ref_id,a.lifecycle_status,a.protocol_outcome,a.reason_code,FROM_UNIXTIME(a.submitted_at/1000) submitted_at,FROM_UNIXTIME(a.result_at/1000) result_at,FROM_UNIXTIME(a.released_at/1000) released_at,FROM_UNIXTIME(a.created_at/1000) created_at,FROM_UNIXTIME(a.updated_at/1000) updated_at FROM pull_task_pull_call_member_attempt a WHERE a.participant_ref_id IN (94850,96415) AND a.participant_type=1 ORDER BY a.participant_ref_id,a.id;
SELECT 'CURRENT_PULLER' section,r.group_execution_id,r.account_id,r.availability_status,r.membership_status,s.account_state,s.login_state,s.mute_status,s.restriction_reason_code,FROM_UNIXTIME(s.pulling_restriction_until/1000) restricted_until FROM pull_task_group_account r JOIN account_state s ON s.account_id=r.account_id WHERE r.task_id=@task_id AND r.group_execution_id IN (507,508,509,510,500) AND r.role_type=2 ORDER BY r.group_execution_id,r.id;
